```javascript
/**
 * In-memory data store for Todos.
 */

const todos = new Map();

// Helper function to generate unique IDs (simple UUID simulation)
let nextId = 1;

/**
 * Creates a new todo item.
 * @param {object} title - The title of the todo.
 * @returns {object} The created todo object.
 */
const createTodo = (title) => {
    const id = String(nextId++);
    const now = new Date().toISOString();

    const todo = {
        id: id,
        title: title,
        completed: false, // Default value
        createdAt: now,
        updatedAt: now
    };

    todos.set(id, todo);
    return todo;
};

/**
 * Retrieves all todos, optionally filtered by completion status.
 * @param {boolean | null} [filterCompleted] - True for completed, false for incomplete, null/undefined for all.
 * @returns {Array<object>} List of todos.
 */
const getTodos = (filterCompleted) => {
    if (filterCompleted === true) {
        return Array.from(todos.values()).filter(t => t.completed);
    }
    if (filterCompleted === false) {
        return Array.from(todos.values()).filter(t => !t.completed);
    }
    return Array.from(todos.values());
};

/**
 * Retrieves a single todo by ID.
 * @param {string} id - The ID of the todo.
 * @returns {object | undefined} The todo object or undefined if not found.
 */
const getTodoById = (id) => {
    return todos.get(id);
};

/**
 * Updates an existing todo item.
 * @param {string} id - The ID of the todo to update.
 * @param {object} updates - Fields to update ({ title?, completed?}).
 * @returns {object | undefined} The updated todo object or undefined if not found.
 */
const updateTodo = (id, updates) => {
    const existingTodo = todos.get(id);
    if (!existingTodo) return undefined;

    // Apply updates while maintaining structure and handling types
    let newTitle = updates.title !== undefined ? String(updates.title).trim() : existingTodo.title;
    let newCompleted = typeof updates.completed === 'boolean' ? updates.completed : existingTodo.completed;

    const updatedTodo = {
        ...existingTodo,
        title: newTitle,
        completed: newCompleted,
        updatedAt: new Date().toISOString() // Always update timestamp
    };

    todos.set(id, updatedTodo);
    return updatedTodo;
};

/**
 * Deletes a todo item by ID.
 * @param {string} id - The ID of the todo to delete.
 * @returns {boolean} True if deleted, false otherwise.
 */
const deleteTodo = (id) => {
    if (!todos.has(id)) return false;
    todos.delete(id);
    return true;
};

module.exports = {
    createTodo,
    getTodos,
    getTodoById,
    updateTodo,
    deleteTodo
};
