### `app.js`

```javascript
const express = require('express');
const cors = require('cors');
const { createTodo, getTodos, getTodoById, updateTodo, deleteTodo } = require('./todoStore');

// Initialize the Express application
const app = express();

// Middleware setup
app.use(cors()); // CORS enabled for all origins
app.use(express.json()); // Handle JSON request bodies

/**
 * Helper function to validate title input.
 * @param {string} title - The title string.
 * @returns {boolean} True if valid, false otherwise.
 */
const isValidTitle = (title) => {
    return typeof title === 'string' && title.trim().length >= 1 && title.trim().length <= 100;
};


// --- Routes ---

/**
 * GET /todos - list all todos with optional filter
 * Supports ?completed=true or ?completed=false
 */
app.get('/todos', (req, res) => {
    const filter = req.query.completed;

    let filteredTodos;
    if (filter === 'true') {
        filteredTodos = getTodos(true);
    } else if (filter === 'false') {
        filteredTodos = getTodos(false);
    } else {
        // No filter provided, return all
        filteredTodos = getTodos(null);
    }

    res.status(200).json(filteredTodos);
});


/**
 * GET /todos/:id - get single todo
 */
app.get('/todos/:id', (req, res) => {
    const todo = getTodoById(req.params.id);

    if (!todo) {
        return res.status(404).json({ message: `Todo with ID ${req.params.id} not found.` });
    }

    res.status(200).json(todo);
});


/**
 * POST /todos - create todo
 */
app.post('/todos', (req, res) => {
    const { title } = req.body;

    // Validation: Title required and valid length/type
    if (!title || !isValidTitle(title)) {
        return res.status(400).json({ 
            message: 'Validation Error: Title is required, must be a string between 1 and 100 characters.' 
        });
    }

    try {
        const newTodo = createTodo(title);
        res.status(201).json(newTodo); // 201 Created
    } catch (error) {
        console.error("Error creating todo:", error);
        res.status(500).json({ message: 'Internal Server Error while creating the todo.' });
    }
});


/**
 * PUT /todos/:id - update todo
 */
app.put('/todos/:id', (req, res) => {
    const id = req.params.id;
    const updates = req.body;

    // Basic validation for the overall request body structure
    if (!updates || Object.keys(updates).length === 0) {
        return res.status(400).json({ message: 'Validation Error: Request body cannot be empty.' });
    }

    // Check if the todo exists first (to provide a specific 404 before update attempt)
    if (!getTodoById(id)) {
         return res.status(404).json({ message: `Todo with ID ${id} not found.` });
    }

    // Specific title validation if provided
    if (updates.title !== undefined && !isValidTitle(updates.title)) {
        return res.status(400).json({ 
            message: 'Validation Error: Title must be a string between 1 and 100 characters.' 
        });
    }

    try {
        const updatedTodo = updateTodo(id, updates);

        if (!updatedTodo) { // Should theoretically not happen if initial check passed, but good practice.
            return res.status(404).json({ message: `Could not find todo with ID ${id} for updating.` });
        }

        res.status(200).json(updatedTodo);
    } catch (error) {
        console.error(`Error updating todo ${id}:`, error);
        res.status(500).json({ message: 'Internal Server Error while updating the todo.' });
    }
});


/**
 * DELETE /todos/:id - delete todo
 */
app.delete('/todos/:id', (req, res) => {
    const id = req.params.id;

    if (!getTodoById(id)) {
        return res.status(404).json({ message: `Todo with ID ${id} not found.` });
    }

    // Attempt deletion
    const wasDeleted = deleteTodo(id);

    if (wasDeleted) {
        res.status(204).send(); // 204 No Content on successful deletion
    } else {
        // Fallback for safety, though the initial check should catch this.
        res.status(404).json({ message: `Todo with ID ${id} not found.` });
    }
});


// Export the app instance for testing purposes (Supertest)
module.exports = app;

// If run directly (e.g., using 'npm start'), start listening on port 3000
if (require.main === module) {
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
        console.log(`🚀 ToDo API running on http://localhost:${PORT}`);
    });
}
