const request = require('supertest');
const app = require('./app'); // Import the exported express app instance

describe('ToDo List API Endpoints', () => {
    let createdTodoId; // To hold an ID for subsequent tests (PUT, DELETE)

    // Helper to create a todo before the test suite runs
    beforeAll(async () => {
        const response = await request(app)
            .post('/todos')
            .send({ title: 'Initial Setup Task' })
            .expect('Content-Type', /json/)
            .expect(201);
        createdTodoId = response.body.id;
    });

    // Clean up the created todo after all tests run
    afterAll(async () => {
        await request(app)
            .delete(`/todos/${createdTodoId}`)
            .expect(204);
    });

    describe('GET /todos', () => {
        test('should list all todos when no filter is provided (Should return at least one item)', async () => {
            const response = await request(app).get('/todos');
            expect(response.statusCode).toBe(200);
            // Since we only created one, it should contain at least that one plus potentially others if run in isolation
            expect(Array.isArray(response.body)).toBe(true);
        });

        test('should list all incomplete todos when ?completed=false is filtered', async () => {
            const response = await request(app).get('/todos?completed=false');
            expect(response.statusCode).toBe(200);
            // Expect the structure to be correct and array-like
        });

        test('should list all completed todos when ?completed=true is filtered', async () => {
            // Simulate creating a completed todo first, then filter by it (for robust testing)
            await request(app).put(`/todos/${createdTodoId}`, { title: 'Completed Task', completed: true }).expect(200);

            const response = await request(app).get('/todos?completed=true');
            expect(response.statusCode).toBe(200);
            // Check if the returned list contains at least one item (the one we marked complete)
            expect(response.body.length).toBeGreaterThanOrEqual(1);
        });
    });

    describe('GET /todos/:id', () => {
        test('should retrieve a single todo by valid ID', async () => {
            const response = await request(app).get(`/todos/${createdTodoId}`);
            expect(response.statusCode).toBe(200);
            expect(response.body).toHaveProperty('id', createdTodoId);
        });

        test('should return 404 if the todo ID does not exist', async () => {
            const response = await request(app).get('/todos/nonExistentId');
            expect(response.statusCode).toBe(404);
            expect(response.body).toHaveProperty('message');
        });
    });

    describe('POST /todos (Create)', () => {
        test('should create a new todo and return 201', async () => {
            const newTitle = 'Buy Milk';
            const response = await request(app)
                .post('/todos')
                .send({ title: newTitle })
                .expect('Content-Type', /json/)
                .expect(201);

            expect(response.body).toHaveProperty('id');
            expect(response.body.title).toBe(newTitle);
            expect(response.body.completed).toBe(false);
        });

        test('should return 400 if title is missing', async () => {
            const response = await request(app)
                .post('/todos')
                .send({});
            expect(response.statusCode).toBe(400);
        });

        test('should return 400 if title is too short (empty string)', async () => {
            const response = await request(app)
                .post('/todos')
                .send({ title: '   ' }); // Whitespace only
            expect(response.statusCode).toBe(400);
        });

         test('should return 400 if title exceeds length limit (101 chars)', async () => {
            const longTitle = 'A'.repeat(101);
            const response = await request(app)
                .post('/todos')
                .send({ title: longTitle });
            expect(response.statusCode).toBe(400);
        });
    });

    describe('PUT /todos/:id (Update)', () => {
        test('should update the completed status of a todo', async () => {
            const updates = { completed: true };
            await request(app)
                .put(`/todos/${createdTodoId}`)
                .send(updates)
                .expect('Content-Type', /json/)
                .expect(200);

            // Verify update by fetching the resource again
            const response = await request(app).get(`/todos/${createdTodoId}`);
            expect(response.body.completed).toBe(true);
        });

        test('should update the title of a todo', async () => {
            const newTitle = 'Updated Awesome Task';
