                .put(`/todos/${createdTodoId}`)
                .send({ title: newTitle })
                .expect('Content-Type', /json/)
                .expect(200);

            // Verify update by fetching the resource again
            const response = await request(app).get(`/todos/${createdTodoId}`);
            expect(response.body.title).toBe(newTitle);
