                .put('/todos/nonExistentId', updates)
                .expect(404);
        });

        test('should return 400 if validation fails (title too long)', async () => {
             const longTitle = 'B'.repeat(101);
            await request(app)
                .put(`/todos/${createdTodoId}`)
                .send({ title: longTitle })
                .expect(400);
        });
    });

    describe('DELETE /todos/:id (Delete)', () => {
        test('should successfully delete an existing todo and return 204', async () => {
            await request(app)
                .delete(`/todos/${createdTodoId}`)
                .expect(204);
        });

        test('should return 404 if trying to delete a non-existent todo', async () => {
             await request(app)
                .delete('/todos/nonExistentId')
                .expect(404);
        });
    });
